sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float beat;
uniform float beatTime;
uniform float beatIndex;
uniform float strength;
uniform float decay;
uniform float beats;
uniform float offset;
uniform float bpm;
half4 main(float2 xy) {
    float2 c = size * 0.5;
    return image.eval(c + (xy - c) / max(1.0 + strength * beat, 0.05));
}
